import{bV as s,aL as i,u as e,G as t}from"./chunks/framework.D_inzUUb.js";const k=JSON.parse('{"title":"KMS 激活 Windows","description":"","frontmatter":{"title":"KMS 激活 Windows","date":"2019-06-13T00:00:00.000Z","categories":["Windows"],"tags":["KMS","Windows","激活"]},"headers":[],"relativePath":"posts/201906/13-kms.md","filePath":"posts/201906/13-kms.md","lastUpdated":1776728300000}'),n={name:"posts/201906/13-kms.md"};function l(r,a,h,o,p,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="kms-激活-windows" tabindex="-1">KMS 激活 Windows <a class="header-anchor" href="#kms-激活-windows" aria-label="Permalink to &quot;KMS 激活 Windows&quot;">​</a></h1><p>以管理员身份运行 cmd，按以下步骤操作：</p><h2 id="_1-卸载之前的密钥" tabindex="-1">1. 卸载之前的密钥 <a class="header-anchor" href="#_1-卸载之前的密钥" aria-label="Permalink to &quot;1. 卸载之前的密钥&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /upk</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr.vbs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /upk</span></span></code></pre></div><p>弹出窗口显示「成功地卸载了产品密钥」。如果提示找不到密钥，不用管，直接跳到下一步。</p><h2 id="_2-安装产品密钥" tabindex="-1">2. 安装产品密钥 <a class="header-anchor" href="#_2-安装产品密钥" aria-label="Permalink to &quot;2. 安装产品密钥&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /ipk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> W269N-WFGWX-YVC9B-4J6C9-T83GX</span></span></code></pre></div><p>弹出窗口显示「成功地安装了产品密钥」。</p><h2 id="_3-设置密钥管理服务器" tabindex="-1">3. 设置密钥管理服务器 <a class="header-anchor" href="#_3-设置密钥管理服务器" aria-label="Permalink to &quot;3. 设置密钥管理服务器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /skms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kms.cangshui.net</span></span></code></pre></div><p>弹出窗口提示「密钥管理服务计算机名称成功地设置为 kms.cangshui.net」。网络上非常多这种 KMS 服务器。</p><h2 id="_4-激活产品" tabindex="-1">4. 激活产品 <a class="header-anchor" href="#_4-激活产品" aria-label="Permalink to &quot;4. 激活产品&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /ato</span></span></code></pre></div><p>弹出窗口提示「成功地激活了产品」。</p><h2 id="_5-查看激活信息" tabindex="-1">5. 查看激活信息 <a class="header-anchor" href="#_5-查看激活信息" aria-label="Permalink to &quot;5. 查看激活信息&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看激活过期时间</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /xpr</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看详细激活信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slmgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dlv</span></span></code></pre></div><h2 id="常用-gvlk-密钥" tabindex="-1">常用 GVLK 密钥 <a class="header-anchor" href="#常用-gvlk-密钥" aria-label="Permalink to &quot;常用 GVLK 密钥&quot;">​</a></h2><p>不同版本的 Windows / Office 需要使用不同的 KMS 客户端安装密钥（GVLK），上文使用的 <code>W269N-WFGWX-YVC9B-4J6C9-T83GX</code> 适用于 Windows 10/11 Pro。</p><p>更多版本的密钥请查看微软官方文档：</p><ul><li><strong>Windows</strong>：<a href="https://learn.microsoft.com/zh-cn/windows-server/get-started/kms-client-activation-keys" target="_blank" rel="noreferrer">KMS 客户端安装密钥</a></li><li><strong>Office</strong>：<a href="https://learn.microsoft.com/zh-cn/DeployOffice/vlactivation/gvlks" target="_blank" rel="noreferrer">Office GVLK 密钥</a></li></ul><h2 id="kms-服务器" tabindex="-1">KMS 服务器 <a class="header-anchor" href="#kms-服务器" aria-label="Permalink to &quot;KMS 服务器&quot;">​</a></h2><p>网络上有很多公开的 KMS 服务器，可参考：</p><ul><li><a href="https://www.coolhub.top/archives/14/comment-page-8" target="_blank" rel="noreferrer">KMS 服务器合集 - CoolHub</a></li></ul><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/DeployOffice/vlactivation/gvlks" target="_blank" rel="noreferrer">Windows KMS 客户端激活密钥（英文）</a></li><li><a href="https://learn.microsoft.com/zh-cn/windows-server/get-started/kms-client-activation-keys" target="_blank" rel="noreferrer">Windows Server KMS 客户端激活密钥</a></li><li><a href="https://learn.microsoft.com/zh-cn/DeployOffice/vlactivation/gvlks" target="_blank" rel="noreferrer">Office GVLK 密钥</a></li></ul>`,25)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
